# Find all hollow regions and fill them
# Rule: 3x3 → 7, anything 5x5+ → 2

def is_hollow(r0, c0, size, grid):
    """Check if this is a hollow region"""
    border_val = grid[r0][c0]

    # Check uniform border
    for r in range(r0, r0+size):
        if grid[r][c0] != border_val or grid[r][c0+size-1] != border_val:
            return False
    for c in range(c0, c0+size):
        if grid[r0][c] != border_val or grid[r0+size-1][c] != border_val:
            return False

    # Check interior has at least one non-border
    for r in range(r0+1, r0+size-1):
        for c in range(c0+1, c0+size-1):
            if grid[r][c] != border_val:
                return True
    return False

